<?php
use DigiForge\PortalAccess\{Authentication,EmailAuthentication,Owner,Session};
require_once __DIR__.'/fixtures/PortalAccessFixture.php';
final class Completion16Test extends WP_UnitTestCase {
 private array $mail=[];private $mailer;
 protected function setUp():void{parent::setUp();PortalAccessFixture::reset();$this->mailer=function($pre,$m){$this->mail[]=$m;return true;};add_filter('pre_wp_mail',$this->mailer,PHP_INT_MAX,2);}
 protected function tearDown():void{remove_filter('pre_wp_mail',$this->mailer,PHP_INT_MAX);global $wpdb;$wpdb->query('COMMIT');PortalAccessFixture::reset();$wpdb->query('COMMIT');$wpdb->query('START TRANSACTION');parent::tearDown();}
 private function request(string $return):array {return Authentication::process(['email'=>Owner::EMAIL,'return_to'=>$return,'challenge'=>Authentication::browserChallenge(),'_wpnonce'=>wp_create_nonce(Authentication::ACTION)]);}
 private function code():string{preg_match('/\b([0-9]{8})\b/',end($this->mail)['message'],$m);return $m[1];}
 public function testResendPreservesBothShopsAndStoredDestinationWinsOverVerificationTampering():void {
  foreach(['digital','personalized_pod']as $shop){PortalAccessFixture::reset();PortalAccessFixture::enroll();wp_set_current_user(0);$_COOKIE=[];$return=add_query_arg(['df_view'=>'users','df_shop'=>$shop],home_url('/'));$r=$this->request($return);$h=EmailAuthentication::verificationForm($r['selector'],$r['return_to']);preg_match('/href="([^"]+)"/',$h,$m);$url=html_entity_decode($m[1],ENT_QUOTES);$q=[];parse_str(wp_parse_url($url,PHP_URL_QUERY),$q);self::assertSame($return,$q['redirect_to']);self::assertStringNotContainsString($r['selector'],$url);$new=$this->request($q['redirect_to']);$verified=Authentication::process(['step'=>'verify','selector'=>$new['selector'],'code'=>$this->code(),'return_to'=>'https://evil.invalid/','challenge'=>Authentication::browserChallenge(),'_wpnonce'=>wp_create_nonce(Authentication::ACTION)]);self::assertNotWPError($verified);self::assertSame($return,$verified['return_to']);self::assertTrue(Session::valid(DigiForge\PortalAccess\Store::read(1)));}
 }
 public function testUnsafeResendDestinationIsRejected():void {$h=EmailAuthentication::verificationForm(str_repeat('a',48),'https://evil.invalid/');self::assertStringNotContainsString('evil.invalid',$h);}
 private function mutate(string $key,callable $callback):mixed{$r=new WP_REST_Request('POST','/digiforge/v1/launch/candidates/1/build-product');$r->set_header('Idempotency-Key',$key);$m=new ReflectionMethod(DigiForge\REST\LaunchController::class,'mutate');$m->setAccessible(true);return $m->invoke(new DigiForge\REST\LaunchController(),$r,'u3_build_product_1',$callback,201);}
 public function testInterruptedReservationCannotBeResubmittedAndCorrelationIsNonSecret():void {
  $key='private-client-'.wp_generate_uuid4();$storage=hash('sha256','u3_build_product_1|'.$key);$r=$this->mutate($key,static function(){throw new RuntimeException('private-error');});self::assertWPError($r);self::assertSame('PENDING',(new DigiForge\Queue\Idempotency())->status($storage));$called=false;$r=$this->mutate($key,static function()use(&$called){$called=true;return [];});self::assertWPError($r);self::assertFalse($called);global $wpdb;$rows=$wpdb->get_col("SELECT context FROM ".DigiForge\Database\Tables::audit_log()." WHERE event_type IN ('launch_reservation_bound','launch_reservation_outcome')");$raw=implode('',$rows);self::assertStringContainsString(hash('sha256',$storage),$raw);self::assertStringContainsString(hash('sha256',$key),$raw);self::assertStringContainsString('UNKNOWN',$raw);self::assertStringNotContainsString($key,$raw);self::assertStringNotContainsString('private-error',$raw);
 }
 public function testSuccessfulTerminalReceiptCorrelatesWithoutChangingDuplicatePolicy():void {$key=wp_generate_uuid4();$r=$this->mutate($key,static fn()=>['run_key'=>'test-run','product_version'=>['id'=>7]]);self::assertInstanceOf(WP_REST_Response::class,$r);$storage=hash('sha256','u3_build_product_1|'.$key);self::assertSame('SUCCESS',(new DigiForge\Queue\Idempotency())->status($storage));self::assertWPError($this->mutate($key,static fn()=>[]));}
 public function testCallbackErrorKeepsUnknownPendingAndBlocksDuplicate():void {$key=wp_generate_uuid4();self::assertWPError($this->mutate($key,static fn()=>new WP_Error('provider_unknown','private')));self::assertSame('PENDING',(new DigiForge\Queue\Idempotency())->status(hash('sha256','u3_build_product_1|'.$key)));self::assertWPError($this->mutate($key,static fn()=>[]));}
 public function testCorrelationAuditFailureBlocksBeforeCallback():void {global $wpdb;$key=wp_generate_uuid4();$filter=static function($sql){return str_starts_with($sql,'INSERT')&&str_contains($sql,'launch_reservation_bound')?'INSERT INTO df_missing_correlation_table VALUES (1)':$sql;};add_filter('query',$filter);$wpdb->suppress_errors(true);$called=false;try{$r=$this->mutate($key,static function()use(&$called){$called=true;return [];});}finally{remove_filter('query',$filter);$wpdb->suppress_errors(false);}self::assertWPError($r);self::assertFalse($called);self::assertSame('PENDING',(new DigiForge\Queue\Idempotency())->status(hash('sha256','u3_build_product_1|'.$key)));}
 public function testMalformedSubreasonsAreBoundedWithoutPayloads():void {foreach([['bad'=>'value'],[['id'=>0,'state'=>'PENDING','action'=>new stdClass]],[['id'=>3,'state'=>'INVALID','action'=>new stdClass]],[['id'=>3,'state'=>'PENDING','action'=>new stdClass]]]as $i=>$frames){$s=(new DigiForge\Queue\ScheduledTaskReadModel(static fn()=>$frames,static fn()=>[]))->snapshot();self::assertSame(['FRAME_SHAPE','ACTION_ID','ACTION_STATE','ACTION_METHODS'][$i],$s['action_scheduler_query']['subreason_code']);} $s=(new DigiForge\Queue\ScheduledTaskReadModel(static function(){throw new UnexpectedValueException('private-secret');},static fn()=>[]))->snapshot();self::assertSame('UNCLASSIFIED',$s['action_scheduler_query']['subreason_code']);self::assertStringNotContainsString('private-secret',wp_json_encode($s));}
 public function testExpiredAndWrongCodeKeepSafeDestinationForReplacement():void {PortalAccessFixture::enroll();wp_set_current_user(0);$_COOKIE=[];$return=add_query_arg(['df_view'=>'users','df_shop'=>'personalized_pod'],home_url('/'));$r=$this->request($return);$code=$this->code();$h=EmailAuthentication::verificationForm($r['selector'],$r['return_to']);self::assertStringContainsString('name="return_to" value="'.esc_attr($return).'"',$h);global $wpdb;$key=EmailAuthentication::key($r['selector']);$state=json_decode($wpdb->get_var($wpdb->prepare("SELECT option_value FROM {$wpdb->options} WHERE option_name=%s",$key)),true);$state['expires']=time()-1;$wpdb->update($wpdb->options,['option_value'=>wp_json_encode($state)],['option_name'=>$key]);$p=['step'=>'verify','selector'=>$r['selector'],'code'=>$code,'return_to'=>$return,'challenge'=>Authentication::browserChallenge(),'_wpnonce'=>wp_create_nonce(Authentication::ACTION)];self::assertWPError(Authentication::process($p));$new=$this->request($return);$p['selector']=$new['selector'];$p['code']=$this->code();$cookie=$_COOKIE;$m=new ReflectionMethod(Authentication::class,'challengeName');$m->setAccessible(true);$challengeName=$m->invoke(null);$_COOKIE[$challengeName]=str_repeat('b',64);$p['challenge']=$_COOKIE[$challengeName];self::assertWPError(Authentication::process($p));$_COOKIE=$cookie;$p['challenge']=Authentication::browserChallenge();$correct=$p['code'];$p['code']=$correct==='00000000'?'11111111':'00000000';self::assertWPError(Authentication::process($p));$p['code']=$correct;$verified=Authentication::process($p);self::assertNotWPError($verified);self::assertSame($return,$verified['return_to']);self::assertWPError(Authentication::process($p));}
}
